import React, { useEffect, useState } from 'react';
import {
    Card,
    CardContent,
    Typography,
    Chip,
    CircularProgress,
    Grid,
    Box,
    Button,
} from '@mui/material';
import { TrafficProvider } from '../../types';
import { trafficProviderService } from '../../services/api';
import { RequestForm } from '../RequestForm';

export const TrafficProviderList: React.FC = () => {
    const [providers, setProviders] = useState<TrafficProvider[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedProvider, setSelectedProvider] = useState<TrafficProvider | null>(null);
    const [requestFormOpen, setRequestFormOpen] = useState(false);

    useEffect(() => {
        const fetchProviders = async () => {
            try {
                const response = await trafficProviderService.getAll();
                setProviders(response);
            } catch (error) {
                console.error('Error fetching providers:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchProviders();
    }, []);

    const getStatusColor = (status: string) => {
        switch (status.toLowerCase()) {
            case 'active':
                return 'success';
            case 'pending':
                return 'warning';
            case 'inactive':
                return 'error';
            default:
                return 'default';
        }
    };

    const handleRequestClick = (provider: TrafficProvider) => {
        setSelectedProvider(provider);
        setRequestFormOpen(true);
    };

    if (loading) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px">
                <CircularProgress />
            </Box>
        );
    }

    return (
        <Box sx={{ flexGrow: 1, p: 3 }}>
            <Typography variant="h4" gutterBottom>
                Поставщики трафика
            </Typography>
            <Box sx={{ mt: 3 }}>
                <Grid container spacing={3}>
                    {providers.map((provider) => (
                        <Grid item key={provider.id} xs={12} sm={6} md={4}>
                            <Card>
                                <CardContent>
                                    <Typography variant="h6" component="h2">
                                        {provider.name}
                                    </Typography>
                                    <Typography color="textSecondary" gutterBottom>
                                        ID: {provider.id}
                                    </Typography>
                                    <Typography variant="body2" paragraph>
                                        {provider.description}
                                    </Typography>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 2 }}>
                                        <Chip
                                            label={provider.status}
                                            color={getStatusColor(provider.status) as any}
                                            size="small"
                                        />
                                        <Button
                                            variant="contained"
                                            size="small"
                                            onClick={() => handleRequestClick(provider)}
                                        >
                                            Оставить заявку
                                        </Button>
                                    </Box>
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                </Grid>
            </Box>
            {selectedProvider && (
                <RequestForm
                    open={requestFormOpen}
                    onClose={() => {
                        setRequestFormOpen(false);
                        setSelectedProvider(null);
                    }}
                    type="provider"
                    targetId={selectedProvider.id}
                />
            )}
        </Box>
    );
}; 